from flask import Blueprint, request, jsonify, g

bp = Blueprint('api', __name__)

DATABASE = 'app.db'

def get_db():
    db = getattr(g, '_database', None)
    if db is None:
        db = g._database = sqlite3.connect(DATABASE)
        db.row_factory = sqlite3.Row
    return db

@bp.teardown_appcontext
def close_connection(exception):
    db = getattr(g, '_database', None)
    if db is not None:
        db.close()

# ---------- User Endpoints ----------
@bp.route('/api/users', methods=['GET'])
def get_users():
    conn = get_db()
    cur = conn.execute('SELECT id, name, email FROM user')
    users = [dict(row) for row in cur.fetchall()]
    return jsonify({'success': True, 'data': users}), 200

@bp.route('/api/users', methods=['POST'])
def create_user():
    data = request.get_json() or {}
    required = {'id', 'name', 'email'}
    if not required.issubset(data.keys()):
        return jsonify({'success': False, 'error': 'Missing fields'}), 400
    conn = get_db()
    conn.execute(
        'INSERT INTO user (id, name, email) VALUES (?, ?, ?)',
        (data['id'], data['name'], data['email'])
    )
    conn.commit()
    return jsonify({'success': True, 'data': {'id': data['id']}}), 201

@bp.route('/api/users/<int:item_id>', methods=['GET'])
def get_user(item_id):
    conn = get_db()
    cur = conn.execute('SELECT id, name, email FROM user WHERE id = ?', (item_id,))
    row = cur.fetchone()
    if row is None:
        return jsonify({'success': False, 'error': 'User not found'}), 404
    return jsonify({'success': True, 'data': dict(row)}), 200

